import json, sys

data = json.loads(json.loads(sys.stdin.read())['result'])
experiments = data['data']['experiments']

# Find all success/negative/RUNNING experiments
target = []
for exp_id, exp in experiments.items():
    conclusion = exp.get('conclusion', '')
    status = exp.get('status', '')
    if conclusion in ('success', 'negative') or status == 'RUNNING':
        target.append({
            'exp_id': exp_id,
            'status': status,
            'conclusion': conclusion,
            'hypothesis': exp.get('hypothesis', ''),
            'parent': exp.get('parent', ''),
            'description': exp.get('description', '')[:100] if exp.get('description') else ''
        })

for t in sorted(target, key=lambda x: x['exp_id']):
    print(f\"\"\"
=== {t['exp_id']} ===
  status: {t['status']}
  conclusion: {t['conclusion']}
  hypothesis: {t['hypothesis'] or '(MISSING)'}
  parent: {t['parent'] or '(MISSING)'}
  description: {t['description']}
\"\"\")

print(f'\nTotal: {len(target)} experiments to audit')
